<template><SilkRoadWorkspace title="合规分析中心"><section class="head"><div><span>GLOBAL COMPLIANCE</span><h1>选择营销项目开始分析</h1><p>针对商品资料、目标市场和营销表述执行合规检查。</p></div><el-button @click="load">刷新项目</el-button></section><el-table v-loading="loading" :data="projects" empty-text="暂无可分析项目"><el-table-column label="商品" prop="product_name" min-width="220"/><el-table-column label="目标市场" min-width="180"><template #default="scope">{{ scope.row.target_markets.join('、')||'待设置' }}</template></el-table-column><el-table-column label="合规评分" prop="compliance_score" width="120"/><el-table-column label="合规状态" width="130"><template #default="scope"><el-tag>{{ label(scope.row.compliance_status) }}</el-tag></template></el-table-column><el-table-column label="操作" width="150"><template #default="scope"><el-button type="primary" link @click="router.push(`/projects/${scope.row.id}/compliance`)">查看分析</el-button></template></el-table-column></el-table><el-empty v-if="!loading&&!projects.length" description="创建营销项目后即可进行目标市场合规分析"><el-button type="primary" @click="router.push('/projects/create')">创建营销项目</el-button></el-empty></SilkRoadWorkspace></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import{useRouter}from'vue-router';import SilkRoadWorkspace from '@/layouts/SilkRoadWorkspace.vue';import{projectAPI}from'@/api/project';import type{MarketingProject}from'@/types/project';const router=useRouter(),projects=ref<MarketingProject[]>([]),loading=ref(false);const label=(s:string)=>({green:'合规通过',yellow:'需要优化',red:'高风险',pending:'待分析'}[s]||'待分析');const load=async()=>{loading.value=true;try{projects.value=(await projectAPI.list({page_size:100})).items}finally{loading.value=false}};onMounted(load)</script>
<style scoped>.head{display:flex;align-items:end;justify-content:space-between;margin-bottom:24px}.head span{font-size:12px;letter-spacing:.16em;color:var(--accent);font-weight:800}.head h1{font-size:30px;margin:8px 0}.head p{color:var(--text-secondary)}</style>
